    #[cfg(all(feature = "std", target_os = "linux"))]
    #[allow(clippy::too_many_arguments)]
    pub fn batched_timeout_generic<EM, OF, Z>(
        user_hooks: HT,
        harness_fn: HB,
        exposed_executor_state: ES,
        observers: OT,
        fuzzer: &mut Z,
